CREATE TABLE t2(a INTEGER PRIMARY KEY,b,c,d,e,f TEXT,g); WITH RECURSIVE x(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM x WHERE i<100) INSERT INTO t2 SELECT i,i*11,((i+2)/3)*1001,i*1.001,((i+2)/3)*100.1,substr('abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz',(i%26)+1,9),substr('zyxwvutsrqponmlkjihgfedcbazyxwvutsrqponmlkjihgfedcba',((i+2)/5)+2,7) FROM x; CREATE INDEX t2b ON t2(b); CREATE INDEX t2c ON t2(c); CREATE INDEX t2d ON t2(d); CREATE INDEX t2e ON t2(e); CREATE INDEX t2f ON t2(f); CREATE INDEX t2g ON t2(g); CREATE TABLE t3(a INTEGER PRIMARY KEY,b,c,d,e,f TEXT,g); INSERT INTO t3 SELECT * FROM t2; CREATE INDEX t3b ON t3(b,c); CREATE INDEX t3c ON t3(c,e); CREATE INDEX t3d ON t3(d,g); CREATE INDEX t3e ON t3(e,f,g); CREATE INDEX t3f ON t3(f,b,d,c); CREATE INDEX t3g ON t3(g,f);